                        <div class="product-price">$${product.price}</div>
                        <div class="product-original-price">$${product.originalPrice}</div>
                    </div>
                    <div class="product-discount">-${discountPercent}%</div>
                </div>
                <button class="add-to-cart-btn" onclick="addToCart(${product.id})">Add to Cart</button>
            </div>
        </div>
    `;
}

function renderDealCard(product) {
    return `
        <div class="deal-card">
            <div class="deal-image">
                ${product.emoji}
                <div class="deal-discount-badge">
                    <div class="deal-discount-amount">${product.discount}%</div>
                    <div class="deal-discount-label">OFF</div>
                </div>
            </div>
            <div class="deal-info">
                <h3 class="deal-name">${product.name}</h3>
                <div class="deal-availability">${product.availability}</div>
                <div class="deal-pricing">
                    <div class="deal-price">$${product.price}</div>
                    <div class="deal-original">$${product.originalPrice}</div>
                </div>
                <button class="add-to-cart-btn" onclick="addToCart(${product.id})">Shop Now</button>
            </div>
        </div>
    `;
}

function renderEditorialCard(article) {
    return `
        <div class="editorial-card">
            <div class="editorial-image">
                ${article.emoji}
                <div class="editorial-tag">${article.tag}</div>
            </div>
            <div class="editorial-content">
                <div class="editorial-date">${article.date}</div>
                <h3 class="editorial-title">${article.title}</h3>
                <p class="editorial-excerpt">${article.excerpt}</p>
                <a href="#" class="read-more">Read Article →</a>
            </div>
        </div>
    `;
}

// ===== Initialize Components =====

function initializeFeaturedProducts() {
    const container = document.getElementById('featured-products');
    if (container) {
        container.innerHTML = featuredProducts
            .map(product => renderProductCard(product))
            .join('');
    }
}

function initializeDealProducts() {
    const container = document.getElementById('deals-products');
    if (container) {
        container.innerHTML = dealProducts
            .map(product => renderDealCard(product))
            .join('');
    }
}

function initializeEditorialContent() {
    const container = document.getElementById('editorial-content');
    if (container) {
        container.innerHTML = editorialContent
            .map(article => renderEditorialCard(article))
            .join('');
    }
}

// ===== Cart Management =====

let cartItems = [];

function addToCart(productId) {
    const allProducts = [...featuredProducts, ...dealProducts];
    const product = allProducts.find(p => p.id === productId);

    if (product) {
        const existingItem = cartItems.find(item => item.id === productId);

        if (existingItem) {
            existingItem.quantity += 1;
        } else {
            cartItems.push({
                ...product,
                quantity: 1,
            });
        }

        updateCartCount();
        showCartNotification(product.name);
    }
}

function updateCartCount() {
    const cartCount = document.querySelector('.cart-count');
    if (cartCount) {
        const totalItems = cartItems.reduce((sum, item) => sum + item.quantity, 0);
        cartCount.textContent = totalItems;
    }
}

function showCartNotification(productName) {
    // Simple visual feedback
    const cartBtn = document.querySelector('.cart-btn');
    if (cartBtn) {
        cartBtn.style.transform = 'scale(1.2)';
        setTimeout(() => {
            cartBtn.style.transform = 'scale(1)';
        }, 300);
    }
}

// ===== Countdown Timer =====

function initializeCountdownTimer() {
    const endTime = new Date();
    endTime.setHours(endTime.getHours() + 24);

    function updateTimer() {
        const now = new Date();
        const timeLeft = endTime - now;

        if (timeLeft > 0) {
            const days = Math.floor(timeLeft / (1000 * 60 * 60 * 24));
            const hours = Math.floor((timeLeft % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((timeLeft % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((timeLeft % (1000 * 60)) / 1000);

            document.getElementById('days').textContent = String(days).padStart(2, '0');
            document.getElementById('hours').textContent = String(hours).padStart(2, '0');
            document.getElementById('minutes').textContent = String(minutes).padStart(2, '0');
            document.getElementById('seconds').textContent = String(seconds).padStart(2, '0');
        } else {
            clearInterval(timerInterval);
        }
    }

    updateTimer();
    const timerInterval = setInterval(updateTimer, 1000);
}

// ===== Newsletter Subscription =====

function initializeNewsletter() {
    const form = document.getElementById('newsletter-form');
    if (form) {
        form.addEventListener('submit', function(e) {
            e.preventDefault();
            const email = this.querySelector('input[type="email"]').value;

            // Show success message
            const originalButton = this.querySelector('button');
            const originalText = originalButton.textContent;
            originalButton.textContent = 'Subscribed! ✓';
            originalButton.style.backgroundColor = 'var(--accent-gold)';

            setTimeout(() => {
                originalButton.textContent = originalText;
                originalButton.style.backgroundColor = '';
                this.reset();
            }, 3000);
        });
    }
}

// ===== Initialize All =====

document.addEventListener('DOMContentLoaded', function() {
    initializeFeaturedProducts();
    initializeDealProducts();
    initializeEditorialContent();
    initializeCountdownTimer();
    initializeNewsletter();
});
