/* ===== CSS Variables ===== */
:root {
    --primary-dark: #0f0f0f;
    --secondary-dark: #1a1a1a;
    --tertiary-dark: #2a2a2a;
    --accent-gold: #d4af37;
    --accent-white: #f5f5f5;
    --accent-gray: #808080;
    --border-color: #3a3a3a;
    --shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
    --shadow-lg: 0 20px 60px rgba(0, 0, 0, 0.7);
    --transition: all 0.3s ease;
}

/* ===== Reset & Base ===== */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', sans-serif;
    background-color: var(--primary-dark);
    color: var(--accent-white);
    line-height: 1.6;
    overflow-x: hidden;
}

/* ===== Utilities ===== */
.container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 2rem;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2.5rem;
    font-weight: 300;
    letter-spacing: 2px;
    text-transform: uppercase;
}

.section-subtitle {
    color: var(--accent-gray);
    margin-top: 0.5rem;
}

.view-all {
    color: var(--accent-gold);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 500;
    transition: var(--transition);
}

.view-all:hover {
    color: var(--accent-white);
    text-decoration: underline;
}

/* ===== Buttons ===== */
.btn {
    padding: 0.875rem 2rem;
    border: none;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    text-transform: uppercase;
    letter-spacing: 1px;
    transition: var(--transition);
    border-radius: 2px;
}

.btn-primary {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
}

.btn-primary:hover {
    background-color: var(--accent-white);
    transform: translateY(-2px);
    box-shadow: 0 15px 30px rgba(212, 175, 55, 0.3);
}

.btn-secondary {
    background-color: transparent;
    color: var(--accent-gold);
    border: 2px solid var(--accent-gold);
}

.btn-secondary:hover {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
}

/* ===== Navigation ===== */
.navbar {
    background-color: var(--primary-dark);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 1000;
    backdrop-filter: blur(10px);
}

.nav-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 1rem 2rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo-text {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 3px;
    color: var(--accent-gold);
}

.nav-menu {
    display: flex;
    gap: 3rem;
}

.nav-link {
    color: var(--accent-white);
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 500;
    transition: var(--transition);
    position: relative;
}

.nav-link:hover {
    color: var(--accent-gold);
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--accent-gold);
    transition: var(--transition);
}

.nav-link:hover::after {
    width: 100%;
}

.nav-actions {
    display: flex;
    gap: 1.5rem;
    align-items: center;
}

.icon-btn {
    background: none;
    border: none;
    color: var(--accent-white);
    cursor: pointer;
    transition: var(--transition);
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
}

.icon-btn:hover {
    color: var(--accent-gold);
    transform: scale(1.1);
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    width: 20px;
    height: 20px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    font-weight: 700;
}

/* ===== Hero Section ===== */
.hero {
    position: relative;
    height: 600px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.hero-background {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, #1a1a1a 0%, #2d2d1a 50%, #1a1a1a 100%);
    z-index: -1;
}

.hero-background::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-image: 
        radial-gradient(circle at 20% 50%, rgba(212, 175, 55, 0.1) 0%, transparent 50%),
        radial-gradient(circle at 80% 80%, rgba(212, 175, 55, 0.05) 0%, transparent 50%);
    animation: float 6s ease-in-out infinite;
}

@keyframes float {
    0%, 100% { transform: translateY(0px); }
    50% { transform: translateY(-20px); }
}

.hero-content {
    position: relative;
    z-index: 1;
    text-align: center;
    animation: fadeInUp 1s ease-out;
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.hero-title {
    font-size: 4rem;
    font-weight: 300;
    letter-spacing: 3px;
    margin-bottom: 1rem;
    color: var(--accent-white);
}

.hero-subtitle {
    font-size: 1.25rem;
    color: var(--accent-gray);
    margin-bottom: 2rem;
    font-weight: 300;
    letter-spacing: 1px;
}

/* ===== Featured Products Section ===== */
.featured-section {
    padding: 5rem 0;
    background-color: var(--primary-dark);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background-color: var(--secondary-dark);
    border: 1px solid var(--border-color);
    overflow: hidden;
    transition: var(--transition);
    cursor: pointer;
    position: relative;
}

.product-card:hover {
    border-color: var(--accent-gold);
    transform: translateY(-8px);
    box-shadow: var(--shadow);
}

.product-image {
    width: 100%;
    height: 280px;
    background: linear-gradient(135deg, var(--tertiary-dark) 0%, var(--secondary-dark) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    overflow: hidden;
    position: relative;
}

.product-image::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(212, 175, 55, 0.1), transparent);
    transition: left 0.5s;
}

.product-card:hover .product-image::before {
    left: 100%;
}

.product-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    padding: 0.25rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    z-index: 2;
}

.product-info {
    padding: 1.5rem;
}

.product-category {
    color: var(--accent-gray);
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 0.5rem;
}

.product-name {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
    font-weight: 500;
    color: var(--accent-white);
}

.product-description {
    color: var(--accent-gray);
    font-size: 0.85rem;
    margin-bottom: 1rem;
    line-height: 1.5;
}

.product-pricing {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.product-price {
    font-size: 1.3rem;
    color: var(--accent-gold);
    font-weight: 600;
}

.product-original-price {
    color: var(--accent-gray);
    text-decoration: line-through;
    font-size: 0.9rem;
}

.product-discount {
    color: #ff6b6b;
    font-size: 0.85rem;
    font-weight: 600;
}

.add-to-cart-btn {
    width: 100%;
    padding: 0.75rem;
    background-color: var(--tertiary-dark);
    border: 1px solid var(--border-color);
    color: var(--accent-white);
    cursor: pointer;
    transition: var(--transition);
    font-size: 0.9rem;
    font-weight: 500;
}

.add-to-cart-btn:hover {
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    border-color: var(--accent-gold);
}

/* ===== Deals Banner ===== */
.deals-banner {
    background: linear-gradient(135deg, var(--secondary-dark) 0%, var(--tertiary-dark) 100%);
    padding: 4rem 0;
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
}

.deals-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    align-items: center;
}

.deals-badge {
    display: inline-block;
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    padding: 0.5rem 1rem;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 1rem;
}

.deals-text h2 {
    font-size: 3rem;
    font-weight: 300;
    letter-spacing: 2px;
    margin-bottom: 0.5rem;
    color: var(--accent-white);
}

.deals-text p {
    font-size: 1.1rem;
    color: var(--accent-gray);
    margin-bottom: 1.5rem;
}

.deals-timer {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 2rem;
}

.timer-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    background-color: var(--primary-dark);
    padding: 1.5rem;
    border: 1px solid var(--border-color);
}

.timer-value {
    font-size: 2rem;
    font-weight: 700;
    color: var(--accent-gold);
    margin-bottom: 0.5rem;
}

.timer-label {
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--accent-gray);
}

/* ===== Deals Section ===== */
.deals-section {
    padding: 5rem 0;
    background-color: var(--primary-dark);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
}

.deal-card {
    position: relative;
    background-color: var(--secondary-dark);
    border: 1px solid var(--border-color);
    overflow: hidden;
    transition: var(--transition);
}

.deal-card:hover {
    border-color: var(--accent-gold);
    transform: translateY(-8px);
    box-shadow: var(--shadow);
}

.deal-image {
    width: 100%;
    height: 200px;
    background: linear-gradient(135deg, var(--tertiary-dark) 0%, var(--secondary-dark) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2.5rem;
    position: relative;
}

.deal-discount-badge {
    position: absolute;
    top: 0;
    right: 0;
    background: linear-gradient(135deg, #ff6b6b, #ff5252);
    color: white;
    padding: 1rem;
    text-align: center;
}

.deal-discount-amount {
    font-size: 1.8rem;
    font-weight: 700;
}

.deal-discount-label {
    font-size: 0.65rem;
    text-transform: uppercase;
}

.deal-info {
    padding: 1.5rem;
}

.deal-name {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
    font-weight: 500;
}

.deal-availability {
    color: var(--accent-gray);
    font-size: 0.8rem;
    margin-bottom: 1rem;
}

.deal-pricing {
    display: flex;
    gap: 1rem;
    margin-bottom: 1rem;
}

.deal-price {
    font-size: 1.4rem;
    color: var(--accent-gold);
    font-weight: 600;
}

.deal-original {
    color: var(--accent-gray);
    text-decoration: line-through;
    align-self: center;
}

/* ===== Editorial Section ===== */
.editorial-section {
    padding: 5rem 0;
    background-color: var(--secondary-dark);
    border-top: 1px solid var(--border-color);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background-color: var(--primary-dark);
    border: 1px solid var(--border-color);
    overflow: hidden;
    transition: var(--transition);
    cursor: pointer;
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    border-color: var(--accent-gold);
    transform: translateY(-8px);
    box-shadow: var(--shadow);
}

.editorial-image {
    width: 100%;
    height: 200px;
    background: linear-gradient(135deg, var(--tertiary-dark) 0%, var(--secondary-dark) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    overflow: hidden;
    position: relative;
}

.editorial-image::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(to top, rgba(0,0,0,0.5), transparent);
}

.editorial-tag {
    position: absolute;
    bottom: 1rem;
    left: 1rem;
    background-color: var(--accent-gold);
    color: var(--primary-dark);
    padding: 0.25rem 0.75rem;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    z-index: 2;
}

.editorial-content {
    padding: 1.5rem;
