    letter-spacing: 1px;
    margin-bottom: 0.5rem;
}

.editorial-title {
    font-size: 1.2rem;
    margin-bottom: 0.75rem;
    font-weight: 500;
    line-height: 1.4;
}

.editorial-excerpt {
    color: var(--accent-gray);
    font-size: 0.9rem;
    margin-bottom: 1rem;
    flex: 1;
}

.read-more {
    color: var(--accent-gold);
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 600;
    transition: var(--transition);
    align-self: flex-start;
}

.read-more:hover {
    color: var(--accent-white);
}

/* ===== Newsletter Section ===== */
.newsletter {
    background: linear-gradient(135deg, var(--secondary-dark) 0%, var(--tertiary-dark) 100%);
    padding: 5rem 0;
    border-top: 1px solid var(--border-color);
}

.newsletter-content {
    text-align: center;
    max-width: 600px;
    margin: 0 auto;
}

.newsletter-content h2 {
    font-size: 2rem;
    margin-bottom: 1rem;
    font-weight: 300;
    letter-spacing: 1px;
}

.newsletter-content p {
    color: var(--accent-gray);
    margin-bottom: 2rem;
    font-size: 1rem;
}

.newsletter-form {
    display: flex;
    gap: 1rem;
}

.newsletter-form input {
    flex: 1;
    padding: 0.875rem 1.5rem;
    background-color: var(--primary-dark);
    border: 1px solid var(--border-color);
    color: var(--accent-white);
    font-size: 0.95rem;
    transition: var(--transition);
}

.newsletter-form input:focus {
    outline: none;
    border-color: var(--accent-gold);
}

.newsletter-form input::placeholder {
    color: var(--accent-gray);
}

/* ===== Footer ===== */
.footer {
    background-color: var(--primary-dark);
    border-top: 1px solid var(--border-color);
    padding: 3rem 0 1rem;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
    margin-bottom: 2rem;
}

.footer-col h3 {
    font-size: 0.95rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 1rem;
    color: var(--accent-gold);
}

.footer-col ul {
    list-style: none;
}

.footer-col ul li {
    margin-bottom: 0.5rem;
}

.footer-col a {
    color: var(--accent-gray);
    text-decoration: none;
    font-size: 0.9rem;
    transition: var(--transition);
}

.footer-col a:hover {
    color: var(--accent-gold);
}

.social-links {
    display: flex;
    gap: 1.5rem;
}

.social-link {
    display: inline-block;
}

